design.css:
/* Coral: the Zangetsu look (docs/theme-references/zangetsu-phone-parity.md). Near-black, one coral
   accent, Nunito, a rounded art card hero glowing in its artwork's colour, and a frosted floating dock
   that folds into an icon pill on scroll. Phone values are Zangetsu's dp (1 CSS px = 1 dp on Android,
   root 16 via mobile.rootSize) and sit under @media (max-width: 640px). Glyphs are Lucide (ISC),
   drawn as masks on [data-dest]. */

@keyframes coral-pop { from { transform: scale(0.7); } to { transform: scale(1); } }
@keyframes coral-fade { from { opacity: 0; } to { opacity: 1; } }
/* FlexibleSpaceBar parallax over the 264 dp collapse (344 → 80): the art rises a quarter as fast as the page
   (0.75 of the scroll back down), then fades into the page colour over the last 56 dp (208 → 264). */
@keyframes coral-parallax { from { transform: translateY(0); } to { transform: translateY(198px); } }
@keyframes coral-art-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes coral-rise { from { opacity: 0; transform: translateY(28px) scale(0.94); } to { opacity: 1; transform: none; } }
@keyframes coral-bone { from { background-color: rgb(32 33 42 / 0.3); } to { background-color: rgb(32 33 42 / 0.55); } }
@keyframes coral-spin { to { transform: rotate(360deg); } }

/* ── Desktop hero: the inset art card with an ambient glow ── */
@media (min-width: 641px) {
  [data-slot="home.hero"] {
    margin: 44px 16px 28px !important;
    width: auto !important;
    border-radius: 28px;
    overflow: hidden;
    box-shadow: 0 18px 70px -10px rgb(var(--hero-ambient-rgb, 255 77 87) / 0.55);
  }
}

/* ── Hero card (both layouts): Zangetsu's two scrims, a centred column 20 px in and 40 px up ── */
[data-part="coral.hero"] { border-radius: 28px; overflow: hidden; }
[data-part="coral.art"] img { object-position: 50% 0; }
[data-part="coral.hero"]::after {
  background: none !important;
  background-image:
    linear-gradient(to bottom, rgb(11 11 15 / 0) 42%, rgb(11 11 15 / 0.7) 72%, #0b0b0f 100%),
    linear-gradient(to bottom, rgb(var(--hero-ambient-rgb, 32 33 42) / 0.72) 0%, rgb(var(--hero-ambient-rgb, 32 33 42) / 0.34) 16%,
      rgb(var(--hero-ambient-rgb, 32 33 42) / 0.08) 34%, rgb(var(--hero-ambient-rgb, 32 33 42) / 0) 52%) !important;
}
[data-part="coral.hero"] > :not(:first-child) { z-index: 2; }
[data-part="coral.info"] { padding: 0 20px 40px !important; gap: 0 !important; }
[data-part="coral.logo"] { display: flex; justify-content: center; width: 100% !important; }
[data-part="coral.logo"] img { width: auto !important; height: auto !important; max-width: 100%; max-height: 96px; object-fit: contain; }
[data-part="coral.title"] { line-height: 1.02; letter-spacing: -0.6px; text-shadow: none !important; }
/* One line: three genres, then the episode count (or the year), "   ·   " between, ellipsized whole. */
[data-part="coral.meta"] {
  display: block !important; width: 100%; height: 18px; margin: 12px 0 18px; overflow: hidden !important;
  white-space: nowrap; text-overflow: ellipsis; text-align: center; text-transform: uppercase;
  font-size: 13px; line-height: 18px; font-weight: 600; letter-spacing: 1.8px; color: rgb(255 255 255 / 0.92);
}
[data-part="coral.meta"] * { display: inline !important; overflow: visible !important; }
/* Genres, then "N EPISODES" once more than one episode has aired, else the year (featured_hero.dart:409-417). */
[data-part="coral.meta"] [data-part="coral.one"],
[data-part="coral.meta"] [data-part="coral.eps"]:has([data-part="coral.one"]),
[data-part="coral.meta"] > [data-part="coral.eps"]:not(:has([data-part="coral.one"])) + [data-part="coral.year"] { display: none !important; }
[data-part="coral.meta"] > :is([data-part="coral.eps"], [data-part="coral.year"]):first-child > [data-part="coral.sep"]:first-child,
[data-part="coral.meta"] > [data-part="coral.eps"]:first-child:has([data-part="coral.one"]) + [data-part="coral.year"] > [data-part="coral.sep"]:first-child { display: none !important; }
[data-part="coral.sep"], [data-part="coral.ep-one"], [data-part="coral.ep-many"] { white-space: pre; }
/* Series meta (every layout): "1 Episode" / "N Episodes"; the first item never starts with a separator. */
[data-part="coral.detail-meta"] [data-part="coral.detail-eps"]:has(> [data-part="coral.ep-one"]) > [data-part="coral.ep-many"] { display: none !important; }
[data-part="coral.detail-meta"] > :first-child > [data-part="coral.sep"]:first-child,
[data-part="coral.detail-meta"] > :first-child > :first-child > [data-part="coral.sep"]:first-child,
[data-part="coral.detail-meta"] > :first-child:empty + * > [data-part="coral.sep"]:first-child { display: none !important; }
[data-part="coral.actions"] { gap: 10px !important; }
[data-part="coral.play"] { width: 138px; height: 44px; padding: 0 !important; justify-content: center; gap: 7px !important; letter-spacing: -0.2px; }
/* play_arrow_rounded 20: a 12 px glyph centred in a 20 px box */
[data-part="coral.play"] svg { width: 20px; height: 12px; }
[data-part="coral.glass"] {
  width: 44px; height: 44px; padding: 0 !important; justify-content: center;
  background: rgb(255 255 255 / 0.14) !important; border: 1px solid rgb(255 255 255 / 0.2);
  -webkit-backdrop-filter: none; backdrop-filter: none;
}
[data-part="coral.glass"] svg { stroke-width: 2.3; }
/* Slide dots: 6 px grey dots on a 12 px pitch, the current one a 20 px accent pill. */
[data-part="hero.dot.track"] {
  width: 6px !important; height: 6px !important; border-radius: 3px !important;
  background: rgb(110 110 120 / 0.47) !important; transition: width 250ms ease-out, background-color 250ms ease-out;
}
[data-part="hero.dot"][data-active] [data-part="hero.dot.track"] { width: 20px !important; background: #ff4d57 !important; }

/* ── Cards (every surface): Zangetsu's poster and Continue Watching cells ── */
[data-part="coral.poster"] { border-radius: 12px; overflow: hidden; }
[data-part="coral.poster"]::after {
  content: ""; position: absolute; inset: 35% 0 0; z-index: 1; pointer-events: none;
  background-image: linear-gradient(to top, rgb(11 11 15 / 0.95), rgb(11 11 15 / 0));
}
[data-part="coral.score"] { z-index: 2; margin: 6px; padding: 2px 5px 2px 4px !important; gap: 2px !important; background: rgb(0 0 0 / 0.6); line-height: 1.1; }
[data-part="coral.score"] > * { line-height: 1.1; }
[data-part="coral.rating"] { font-size: 9px !important; letter-spacing: 0.3px; }
[data-part="coral.card-title"] { line-height: 1.3; min-height: 2.6em; }

[data-part="z.cw"] { border-radius: 14px; overflow: hidden; }
[data-part="z.cw"]::after {
  content: ""; grid-area: 1 / 1; z-index: 1; pointer-events: none;
  background-image: linear-gradient(to top, rgb(0 0 0 / 0.85), rgb(0 0 0 / 0) 50%);
}
[data-part="z.cw-text"] { z-index: 2 !important; padding: 0 10px 9px; }
[data-part="z.cw-title"] { line-height: 1.35; }
[data-part="z.cw-ep"] { line-height: 1.3; }
[data-part="z.cw-ep"] > * { line-height: 1.3; }
[data-part="z.cw-progress"] { z-index: 3 !important; height: 4px; min-height: 4px !important; border-radius: 0 !important; background: rgb(255 255 255 / 0.25) !important; }
[data-part="z.cw-progress"] > span { background: #ff4d57 !important; }

@media (max-width: 640px) {
  /* ── Home app bar: 8 px over a 48 px row, 16 px gutters; grey stroke icons in 48 px targets
     (Downloads, Watch Together in the bell's slot, Search) ── */
  [data-slot="home.header"] { position: relative; z-index: 1; padding: 8px 16px 0 !important; }
  [data-slot="home.header"] [data-part="home.header.actions"] { gap: 0 !important; }
  [data-part="home.header.action"] { width: 48px !important; height: 48px !important; color: #a7a7b2 !important; }
  [data-part="home.header.action"] svg { width: 17px; height: 17px; stroke-width: 2.4; }
  /* Watch Together sits in the bell's 30 dp slot between Downloads and Search (home-a.xml 317.3, w 30). */
  [data-part="home.header.action"][data-dest="watch"] { width: 30px !important; }

  /* ── Hero region: the section is Zangetsu's 62 %-of-screen region (380 to 560 px from the screen
     top), the template root is the 28 px card inset 16 at the sides, max(90, inset + 58) from the
     screen top and 40 above the region's end; the art-coloured glow fills the whole region, under
     the app bar and the status bar too. ── */
  [data-slot="home.hero"][data-variant="template"] {
    height: calc(clamp(380px, 62vh, 560px) - max(90px, calc(env(safe-area-inset-top) + 58px)) - 40px) !important;
    min-height: 250px !important;
    margin: max(2px, calc(34px - env(safe-area-inset-top))) 16px 40px !important;
    width: auto !important; overflow: visible !important; isolation: isolate; border-radius: 0; box-shadow: none;
  }
  [data-slot="home.hero"][data-variant="template"]::before {
    content: ""; position: absolute; z-index: -1; pointer-events: none;
    left: -16px; right: -16px; bottom: -40px; top: calc(0px - max(90px, calc(env(safe-area-inset-top) + 58px)));
    background-image: radial-gradient(circle 105vw at 50% 42.5%, rgb(var(--hero-ambient-rgb, 32 33 42) / 0.66) 0%,
      rgb(var(--hero-ambient-rgb, 32 33 42) / 0.28) 50%, rgb(11 11 15 / 0) 84%);
  }
  /* Dots 16 px under the card. */
  [data-slot="home.hero"] [data-part="hero.indicator"] { left: 0 !important; right: 0 !important; bottom: -22px !important; gap: 6px !important; justify-content: center !important; }
  /* Loading: Zangetsu draws no hero placeholder; the header sits on the page colour over the shortcut
     cards and the row bones until the slides land (home_screen.dart:1716-1749). */
  [data-slot="home.hero"][data-state="loading"] { display: none !important; }

  /* ── Shortcut cards (Zangetsu's "Schedule & lists" and "Genres", home_screen.dart:1088-1475): the
     theme's profile-header block, reduced to its two art buttons, 52 tall, r16, 12 apart. Each shows
     one of the viewer's own titles (`art: true`: Lists the last watched, Genres the next) at (0, -0.2)
     under a left → right scrim: Lists #000 .80 → .33, Genres the accent at L 30 % @ .78 → #000 .55.
     Without a title a card is its accent-toned corner gradient alone (Lists L 22 → 11 %, Genres
     L 32 → 15 %), along the card's own diagonal (106deg at 184 x 52), with no scrim. ── */
  [data-slot="block.profile-header"]:has([data-dest="schedule"] + [data-dest="search"]) { margin: 0 !important; padding: 6px 16px !important; }
  [data-slot="block.profile-header"]:has([data-dest="schedule"] + [data-dest="search"]) > div {
    overflow: visible !important; border-radius: 0 !important; background: none !important;
  }
  [data-slot="block.profile-header"]:has([data-dest="schedule"] + [data-dest="search"]) :is([data-part="block.banner"], [data-part="block.scrim"], [data-part="block.profile"]) { display: none !important; }
  [data-slot="block.profile-header"]:has([data-dest="schedule"] + [data-dest="search"]) div:has(> [data-part="button"]) {
    flex-wrap: nowrap !important; gap: 12px !important; padding: 0 !important;
  }
  [data-slot="block.profile-header"] [data-part="button"]:is([data-dest="schedule"]:has(+ [data-dest="search"]), [data-dest="schedule"] + [data-dest="search"]) {
    position: relative; isolation: isolate; overflow: hidden;
    flex: 1 1 0; min-width: 0; display: flex; align-items: center; justify-content: center; gap: 8px;
    height: 52px; padding: 0 12px !important; border-radius: 16px !important;
    background: linear-gradient(106deg, hsl(357 100% 22%), hsl(357 100% 11%)) !important;
    -webkit-backdrop-filter: none !important; backdrop-filter: none !important;
    font-size: 14px !important; line-height: 1.35; font-weight: 700 !important; color: #fff !important;
    text-shadow: 0 0 6px #000; white-space: nowrap;
  }
  [data-slot="block.profile-header"] [data-part="button"][data-dest="schedule"] + [data-part="button"][data-dest="search"] {
    background: linear-gradient(106deg, hsl(357 100% 32%), hsl(357 100% 15%)) !important;
  }
  [data-slot="block.profile-header"] [data-part="button"]:is([data-dest="schedule"]:has(+ [data-dest="search"]), [data-dest="schedule"] + [data-dest="search"]) > [data-part="block.button.art"] { z-index: -2; object-fit: cover; object-position: 50% 40%; }
  [data-slot="block.profile-header"] [data-part="button"]:is([data-dest="schedule"]:has(+ [data-dest="search"]), [data-dest="schedule"] + [data-dest="search"]):has(> [data-part="block.button.art"])::after {
    content: ""; position: absolute; inset: 0; z-index: -1; pointer-events: none;
    background-image: linear-gradient(to right, rgb(0 0 0 / 0.8), rgb(0 0 0 / 0.33));
  }
  [data-slot="block.profile-header"] [data-part="button"][data-dest="schedule"] + [data-part="button"][data-dest="search"]:has(> [data-part="block.button.art"])::after {
    background-image: linear-gradient(to right, hsl(357 100% 30% / 0.78), rgb(0 0 0 / 0.55));
  }
  [data-slot="block.profile-header"] [data-part="button"]:is([data-dest="schedule"]:has(+ [data-dest="search"]), [data-dest="schedule"] + [data-dest="search"])::before {
    content: ""; flex: none; width: 18px; height: 18px; background: currentColor;
    -webkit-mask-repeat: no-repeat; mask-repeat: no-repeat; -webkit-mask-position: center; mask-position: center;
    -webkit-mask-size: contain; mask-size: contain;
  }
  [data-slot="block.profile-header"] [data-part="button"][data-dest="schedule"]:has(+ [data-dest="search"])::before { -webkit-mask-image: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%20fill%3D%27none%27%20stroke%3D%27black%27%20stroke-width%3D%272.2%27%20stroke-linecap%3D%27round%27%20stroke-linejoin%3D%27round%27%3E%3Crect%20x%3D%275.25%27%20y%3D%276.5%27%20width%3D%2713.5%27%20height%3D%2713%27%20rx%3D%272.5%27%20fill%3D%27black%27%2F%3E%3Cpath%20d%3D%27M9%204.2v3%27%2F%3E%3Cpath%20d%3D%27M15%204.2v3%27%2F%3E%3C%2Fsvg%3E); mask-image: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%20fill%3D%27none%27%20stroke%3D%27black%27%20stroke-width%3D%272.2%27%20stroke-linecap%3D%27round%27%20stroke-linejoin%3D%27round%27%3E%3Crect%20x%3D%275.25%27%20y%3D%276.5%27%20width%3D%2713.5%27%20height%3D%2713%27%20rx%3D%272.5%27%20fill%3D%27black%27%2F%3E%3Cpath%20d%3D%27M9%204.2v3%27%2F%3E%3Cpath%20d%3D%27M15%204.2v3%27%2F%3E%3C%2Fsvg%3E); }
  [data-slot="block.profile-header"] [data-part="button"][data-dest="schedule"] + [data-part="button"][data-dest="search"]::before { -webkit-mask-image: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%20fill%3D%27none%27%20stroke%3D%27black%27%20stroke-width%3D%271.9%27%20stroke-linecap%3D%27round%27%20stroke-linejoin%3D%27round%27%3E%3Cpath%20d%3D%27M12.586%202.586A2%202%200%200%200%2011.172%202H4a2%202%200%200%200-2%202v7.172a2%202%200%200%200%20.586%201.414l8.704%208.704a2.426%202.426%200%200%200%203.42%200l6.58-6.58a2.426%202.426%200%200%200%200-3.42z%27%2F%3E%3Ccircle%20cx%3D%277.5%27%20cy%3D%277.5%27%20r%3D%271%27%20fill%3D%27black%27%2F%3E%3C%2Fsvg%3E); mask-image: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%20fill%3D%27none%27%20stroke%3D%27black%27%20stroke-width%3D%271.9%27%20stroke-linecap%3D%27round%27%20stroke-linejoin%3D%27round%27%3E%3Cpath%20d%3D%27M12.586%202.586A2%202%200%200%200%2011.172%202H4a2%202%200%200%200-2%202v7.172a2%202%200%200%200%20.586%201.414l8.704%208.704a2.426%202.426%200%200%200%203.42%200l6.58-6.58a2.426%202.426%200%200%200%200-3.42z%27%2F%3E%3Ccircle%20cx%3D%277.5%27%20cy%3D%277.5%27%20r%3D%271%27%20fill%3D%27black%27%2F%3E%3C%2Fsvg%3E); -webkit-mask-size: 16.3px; mask-size: 16.3px; }

  /* ── Rows: 26 above and 14 below a 17/600 heading, a 13/500 accent link, 16 px gutters
     (28 px after the last card), no bottom padding: a 276.4 px poster-row pitch. ── */
  [data-slot="home"] [data-slot="row"] > [data-part="row.header"] { padding: 26px 16px 0 !important; margin-bottom: 14px !important; align-items: center !important; }
  [data-slot="home"] [data-part="row.title"] { font-size: 17px !important; line-height: 1.2; font-weight: 600 !important; letter-spacing: 0; color: #fff; }
  [data-slot="home"] [data-part="row.more"] {
    margin: -8px 0 !important; padding: 8px 0 8px 8px !important; opacity: 1 !important;
    font-size: 13px !important; line-height: 1.3; font-weight: 500 !important; color: #ff4d57 !important;
  }
  [data-slot="home"] [data-part="row.more"] svg { display: none; }
  [data-slot="home"] [data-part="row.track"] { padding: 0 28px 0 16px !important; scroll-padding-inline: 16px; }
  /* Loading rows (RowSkeleton): a 120 x 16 r6 title bone 20 above and 10 below, then 124 x 210 r12
     bones 12 apart, #20212A pulsing .30 ↔ .55 over 1200 ms; no shimmer, no link. Continue Watching
     keeps its 190 x 107 r14 card shape. */
  [data-slot="home"] [data-slot="row"]:has([data-part="row.skeleton"]) > [data-part="row.header"] { padding-top: 20px !important; margin-bottom: 10px !important; }
  [data-slot="home"] [data-slot="row"]:has([data-part="row.skeleton"]) [data-part="row.title"] {
    flex: none; width: 120px; height: 16px; overflow: hidden; border-radius: 6px; color: transparent !important;
    background-color: rgb(32 33 42 / 0.3);
  }
  [data-slot="home"] [data-slot="row"]:has([data-part="row.skeleton"]) [data-part="row.more"] { visibility: hidden; }
  [data-slot="home"] [data-part="row.skeleton"] {
    width: 124px !important; height: 210px !important; aspect-ratio: auto !important; border-radius: 12px !important;
    background: rgb(32 33 42 / 0.3);
  }
  [data-slot="home"] [data-slot="row"][data-role="continue"] [data-part="row.skeleton"] { width: 190px !important; height: 107px !important; border-radius: 14px !important; }
  [data-slot="home"] [data-part="row.skeleton"]::before { display: none; }

  /* ── Search (Zangetsu's library-scope bar, search_screen.dart:732-818): a #20212A pill, r26, 42 tall
     (11 px content padding around the 15/1.35 text), 14 lead, the grey 20 dp search_rounded glyph
     (Material Icons, Apache-2.0), 10 to the text. ── */
  [data-slot="search"] { padding-top: 12px !important; }
  [data-slot="search"] [data-part="search.field"] {
    height: 42px !important; border: 0 !important; border-radius: 26px !important; padding: 0 16px 0 44px !important;
    background-color: #20212a !important; font-size: 15px !important; line-height: 1.35;
    background-image: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%20fill%3D%27%236E6E78%27%3E%3Cpath%20d%3D%27M15.5%2014h-.79l-.28-.27c1.2-1.4%201.82-3.31%201.48-5.34-.47-2.78-2.79-5-5.59-5.34-4.23-.52-7.79%203.04-7.27%207.27.34%202.8%202.56%205.12%205.34%205.59%202.03.34%203.94-.28%205.34-1.48l.27.28v.79l4.25%204.25c.41.41%201.08.41%201.49%200%20.41-.41.41-1.08%200-1.49L15.5%2014zm-6%200C7.01%2014%205%2011.99%205%209.5S7.01%205%209.5%205%2014%207.01%2014%209.5%2011.99%2014%209.5%2014z%27%2F%3E%3C%2Fsvg%3E); background-repeat: no-repeat; background-position: 14px 50%; background-size: 20px 20px;
  }
  [data-slot="search"] [data-part="search.field"]::placeholder { color: #a7a7b2; }
  /* The header (field and filters) pins at the screen top on the page colour while the results
     scroll, as Zangetsu's bar stays above its scrolling results. Its box reaches up under the status
     bar (the page's top inset and the 12 above the field) and 12 below the filters, so nothing moves
     at rest. */
  [data-slot="search"] [data-slot="search.header"] {
    display: block !important; position: sticky; top: 0; z-index: 20;
    margin: calc(-12px - env(safe-area-inset-top)) -16px -12px; padding: calc(12px + env(safe-area-inset-top)) 16px 12px;
    background-color: #0b0b0f;
  }
  /* Results: the 3-column poster grid, 12 across and 16 down (search_screen.dart, my_list_screen.dart). */
  [data-slot="search"] [data-part="search.grid"][data-variant="grid"] { column-gap: 12px !important; row-gap: 16px !important; }

  /* ── Floating dock: 16 px margins, 9/6 padding, σ20 frost over #16161C @ .55, 1 px white @ .07,
     no shadow, no indicator; 25 px icon rows, 10/1.2 labels (600 when active). Zangetsu's five slots
     map to Home, Library (My List), Schedule in the centre 50 px accent squircle (Zangetsu's mode
     button), Search (the "Sources" slot, a label of the same length) and Settings (Profile).
     Collapsed (scroll chrome, 60 px threshold): labels fold, the pill narrows to 48 px per tab around
     the 50 px squircle (half width 24 N + 7 from --nav-items) and centres, padding 9 → 4, squircle
     50 → 38; 340 ms, Zangetsu's curve. ── */
  [data-slot="nav.bottom"] {
    --coral-dock-ease: cubic-bezier(0.32, 0.72, 0, 1);
    --coral-dock-half: calc(var(--nav-items, 5) * 24px + 7px);
    left: 16px !important; right: 16px !important; padding: 9px 6px; gap: 0 !important;
