/* The art's parallax collapse, driven by the page scroll; never under reduced motion. */
@media (max-width: 640px) and (prefers-reduced-motion: no-preference) {
  :scope:not(.a11y-reduce-motion) [data-slot="detail"][data-variant="phone"] [data-part="detail.backdrop"] {
    animation: coral-parallax linear both; animation-timeline: scroll(root); animation-range: 0 264px;
  }
  /* The fade is a page-colour sheet over the art (the image keeps izumi's own fade-in on load). */
  :scope:not(.a11y-reduce-motion) [data-slot="detail"][data-variant="phone"] [data-slot="detail.banner"]::before {
    content: ""; position: absolute; inset: 0; z-index: 1; pointer-events: none; background-color: #0b0b0f; opacity: 0;
    animation: coral-art-fade linear both; animation-timeline: scroll(root); animation-range: 208px 264px;
  }
}

