  [data-part="card"]:active [data-part="coral.card"], [data-part="card"]:active [data-part="z.cw"] { transform: scale(0.97); }
}

/* Card entrance ("rise", Zangetsu's reveal_item.dart: fade, 28 px up, 0.94 → 1 over 380 ms, a 45 ms
   stagger per eight), phones only and never under reduced motion. Cards sit in a wrapper in the track. */
@media (max-width: 640px) and (prefers-reduced-motion: no-preference) {
  :scope:not(.a11y-reduce-motion) [data-slot="home"] [data-part="row.track"] > * > [data-part="card"] { animation: coral-rise 380ms cubic-bezier(0.215, 0.61, 0.355, 1) both; }
  :scope:not(.a11y-reduce-motion) [data-slot="home"] [data-part="row.track"] > :nth-child(8n + 2) > [data-part="card"] { animation-delay: 45ms; }
  :scope:not(.a11y-reduce-motion) [data-slot="home"] [data-part="row.track"] > :nth-child(8n + 3) > [data-part="card"] { animation-delay: 90ms; }
  :scope:not(.a11y-reduce-motion) [data-slot="home"] [data-part="row.track"] > :nth-child(8n + 4) > [data-part="card"] { animation-delay: 135ms; }
  :scope:not(.a11y-reduce-motion) [data-slot="home"] [data-part="row.track"] > :nth-child(8n + 5) > [data-part="card"] { animation-delay: 180ms; }
  :scope:not(.a11y-reduce-motion) [data-slot="home"] [data-part="row.track"] > :nth-child(8n + 6) > [data-part="card"] { animation-delay: 225ms; }
  :scope:not(.a11y-reduce-motion) [data-slot="home"] [data-part="row.track"] > :nth-child(8n + 7) > [data-part="card"] { animation-delay: 270ms; }
  :scope:not(.a11y-reduce-motion) [data-slot="home"] [data-part="row.track"] > :nth-child(8n + 8) > [data-part="card"] { animation-delay: 315ms; }
  /* The row bones pulse (RowSkeleton: easeInOut, 1200 ms each way). */
  :scope:not(.a11y-reduce-motion) [data-slot="home"] :is([data-part="row.skeleton"], [data-slot="row"]:has([data-part="row.skeleton"]) [data-part="row.title"]) {
    animation: coral-bone 1200ms ease-in-out infinite alternate;
  }
}

/* ══ Series page: Zangetsu's detail screen (zangetsu-phone-parity.md "Series page"). Built on the API 4
   series keys (design.json `mobile.detail`: buttons, synopsis, countdownAt, infoKeys, factsLabels,
   factsFormat, sections) and the series hooks. Glyphs are Material Icons (Apache-2.0), the set
   Zangetsu draws with, as masks. ══ */

