[data-slot="detail"] [data-part="tab"] { font-size: 15px; font-weight: 500; color: #a7a7b2; }
[data-slot="detail"] [data-part="tab"][data-active] { font-weight: 600; color: #ff4d57; }
[data-slot="detail"] [data-part="tab"][data-active] > span { left: 12px; right: 12px; bottom: 0; height: 2.5px; background-color: #ff4d57; }
[data-slot="detail"] [data-part="tabs"][data-variant="underline"] { border-bottom: 0; }

/* The Back button on every phone series bar (the failure bar too): Material arrow_back, 24 px in a
   48 px target. */
[data-part="detail.back"] { width: 48px !important; height: 48px !important; color: #fff; }
[data-part="detail.back"] > svg { display: none; }
[data-part="detail.back"]::before {
  content: ""; width: 24px; height: 24px; background: currentColor;
  -webkit-mask: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%3E%3Cpath%20d%3D%27M20%2011H7.83l5.59-5.59L12%204l-8%208%208%208%201.41-1.41L7.83%2013H20v-2z%27%2F%3E%3C%2Fsvg%3E) center / contain no-repeat; mask: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%3E%3Cpath%20d%3D%27M20%2011H7.83l5.59-5.59L12%204l-8%208%208%208%201.41-1.41L7.83%2013H20v-2z%27%2F%3E%3C%2Fsvg%3E) center / contain no-repeat;
}

