  [data-slot="detail"][data-variant="phone"] [data-slot="detail.relations"] [data-part="coral.score"] { display: none !important; }
  [data-slot="detail"][data-variant="phone"] [data-slot="detail.relations"] [data-part="coral.poster"]::after { display: none; }
  [data-slot="detail"][data-variant="phone"] [data-slot="detail.relations"] [data-part="relation.type"] {
    order: 2; margin: 6px 0 0 !important; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; text-transform: uppercase;
    font-size: 10px !important; line-height: 1.3; font-weight: 700; letter-spacing: 0.4px; color: #ff4d57 !important;
  }
  [data-slot="detail"][data-variant="phone"] [data-slot="detail.relations"] [data-part="coral.card-title"] {
    order: 3; min-height: 0; margin-top: 0; font-size: 13px; line-height: 1.3; font-weight: 500; color: #fff;
  }

  /* ── Details tab (Overview: detail.overview), 20 under the tabs (detail_tabs.dart:412-587): the fact
     rows in Zangetsu's order (infoKeys), a 96 px label column 13 #6E6E78 in sentence case ("Native
     title"), the value 13/600 white, 10 under each; Aired and Ended share one row
     ("start  —  end"); "Also known as" is a row of at most five titles, " · " between; then 14 +
     Genres and 14 + Tags ("Name  NN%") as TagBadge chips, then 20 + the whole synopsis. The
     Information block and its list step aside (display: contents) so every row sits in one wrapping
     column that the rows order. ── */
  [data-slot="detail"][data-variant="phone"] [data-part="detail.overview"] { display: flex; flex-flow: row wrap; align-items: flex-start; margin-top: 20px !important; }
  [data-slot="detail"][data-variant="phone"] :where([data-part="detail.overview"]) > * { order: 5; flex: 0 0 100%; min-width: 0; margin: 20px 0 0 !important; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.info"],
  [data-slot="detail"][data-variant="phone"] [data-part="detail.info"] > dl { display: contents !important; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.info"] > [data-part="detail.block-title"] { display: none; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.info"] [data-part="fact"] {
    order: 1; flex: 0 0 100%; min-width: 0; display: grid !important; grid-template-columns: 96px minmax(0, 1fr); margin: 0 0 10px !important; padding: 0 !important;
    border: 0; border-radius: 0 !important; background: none !important;
  }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.info"] [data-part="fact.label"] {
    font-size: 13px !important; line-height: 1.3; font-weight: 500 !important; letter-spacing: 0 !important; text-transform: lowercase !important; color: #6e6e78 !important;
  }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.info"] [data-part="fact.label"]::first-letter { text-transform: uppercase; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.info"] [data-part="fact.value"] { margin: 0 !important; font-size: 13px; line-height: 1.3; font-weight: 600 !important; color: #fff; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.info"] [data-part="fact.value"] a { color: inherit; text-decoration: none; }
  /* "03/07/2026  —  25/12/2026": the end date joins the Aired row (no label, two spaces each side). */
  [data-slot="detail"][data-variant="phone"] [data-part="detail.info"] [data-part="fact"][data-key="aired"]:has(+ [data-part="fact"][data-key="ended"]) { flex: 0 0 auto; grid-template-columns: 96px auto; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.info"] [data-part="fact"][data-key="aired"] + [data-part="fact"][data-key="ended"] { flex: 1 1 0; display: block !important; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.info"] [data-part="fact"][data-key="aired"] + [data-part="fact"][data-key="ended"] > [data-part="fact.label"] { display: none; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.info"] [data-part="fact"][data-key="aired"] + [data-part="fact"][data-key="ended"] > [data-part="fact.value"]::before { content: "  —  "; white-space: pre; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.synonyms"] { order: 2; display: grid !important; grid-template-columns: 96px minmax(0, 1fr); margin: 0 0 10px !important; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.overview"] [data-part="detail.synonyms"] > [data-part="detail.block-title"] { margin: 0 !important; font-size: 0 !important; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.synonyms"] > [data-part="detail.block-title"]::after { content: "Also known as"; font-size: 13px; line-height: 1.3; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.synonyms"] > :has(> [data-part="chip"]) { font-size: 13px !important; line-height: 1.3 !important; font-weight: 600; color: #fff; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.synonyms"] [data-part="chip"]:nth-child(n + 6) { display: none; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.info"] [data-part="fact"][data-key="genres"] { order: 3; display: block !important; margin: 4px 0 0 !important; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.info"] [data-part="fact"][data-key="genres"] > [data-part="fact.label"] { margin-bottom: 10px; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.info"] [data-part="fact"][data-key="genres"] > [data-part="fact.value"] { font-size: 0 !important; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.tags"] { order: 4; margin: 8px 0 0 !important; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.overview"] [data-part="detail.block-title"] {
    margin: 0 0 8px !important; font-size: 13px !important; line-height: 1.3; font-weight: 500 !important; color: #6e6e78;
  }
  /* The block's heading is "Tags" in Zangetsu (izumi: "Themes"). */
  [data-slot="detail"][data-variant="phone"] [data-part="detail.overview"] [data-part="detail.tags"] > [data-part="detail.block-title"] { margin: 0 0 10px !important; font-size: 0 !important; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.tags"] > [data-part="detail.block-title"]::after { content: "Tags"; font-size: 13px; line-height: 1.3; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.tags"] > :has(> [data-part="chip"]) { gap: 6px !important; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.overview"] p[data-part="detail.synopsis"] { font-size: 15px !important; line-height: 1.35 !important; color: #a7a7b2; }
  /* TagBadge: 12/700/+0.8 #A7A7B2 on #A7A7B2 @ 15 %, r6, 2 / 6 padding, 6 apart (spoiler tags accent);
     a tag ends with its rank, two spaces after the name. */
  [data-slot="detail"][data-variant="phone"] :is([data-part="fact"][data-key="genres"] a, [data-part="detail.tags"] [data-part="chip"]) {
    display: inline-flex !important; align-items: center; min-height: 0 !important; margin: 0 6px 6px 0; padding: 2px 6px !important;
    border: 0 !important; border-radius: 6px !important; background: rgb(167 167 178 / 0.15) !important;
    color: #a7a7b2 !important; font-size: 12px !important; line-height: 17px; font-weight: 700 !important; letter-spacing: 0.8px; text-decoration: none;
  }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.tags"] [data-part="chip"] { margin: 0; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.tags"] button[data-part="chip"] { background: rgb(255 77 87 / 0.15) !important; color: #ff4d57 !important; }
  [data-slot="detail"][data-variant="phone"] [data-part="detail.tags"] [data-part="chip.meta"] { display: inline !important; margin-left: 7.6px; }

  /* ── Loading frame (`data-pending`): the same page from the tapped card, with Zangetsu's bones in the
     places the card cannot fill: synopsis lines at the text's own 20.25 px pitch with room for
     "Read more", grey #20212A. ── */
  [data-slot="detail"][data-pending][data-variant="phone"] button[data-part="detail.synopsis"]:has(.skeloader) { padding-bottom: 22.9px; }
  [data-slot="detail"][data-pending][data-variant="phone"] button[data-part="detail.synopsis"] .skeloader { height: 13px !important; margin: 3.6px 0 !important; border-radius: 6px; }
  [data-slot="detail"][data-pending][data-variant="phone"] [data-part="detail.title"] .skeloader { height: 26px; vertical-align: 2px; border-radius: 6px; }
  [data-slot="detail"][data-pending][data-variant="phone"] [data-part="detail.genres"] { display: none !important; }
  [data-slot="detail"][data-pending][data-variant="phone"] [data-part="detail.actions"] { margin-top: 14px !important; }
  [data-slot="detail"][data-pending][data-variant="phone"] [data-part="detail.lead"] {
    display: block !important; min-height: 37.8px;
    background-image: linear-gradient(#20212a, #20212a), linear-gradient(#20212a, #20212a); background-repeat: no-repeat;
    background-size: 62% 11px, 34% 11px; background-position: 8px 3px, 8px 22px; background-origin: border-box;
  }
  [data-slot="detail"][data-pending][data-variant="phone"] [data-part="detail.lead"] > * { display: none; }
}

/* ══ Text weight (phones). Zangetsu draws Nunito from its bundled variable file with no font variations,
   so on a phone its nominal 400/500/600/700 read lighter than the same CSS weights. Calibrated on the
   Android emulator in the Android System WebView (the engine izumi runs in on Android): izumi's own
   Nunito Variable at a weight ladder, ink-matched to the same strings in the v2.2.0 captures
   (tmp/coral/fix-r1/wcal): 400 at 15 px → 367, 400/500 at 11–13 px → 399–418, 600 → 483–503,
   700 → 657 at 15 px and 672 at 28 px. Windows Chrome (the desktop harness) draws every weight 20–110
   heavier than the phone does. ══ */
@media (max-width: 640px) {
  /* Regular, 14 px and up (Zangetsu 400 and 500 render alike). */
  :scope :is([data-part="coral.detail-meta"], [data-part="coral.detail-meta"] *, [data-slot="search"] [data-part="search.field"],
    [data-slot="detail"][data-variant="phone"] [data-part="detail.synopsis"],
    [data-slot="detail"][data-variant="phone"] [data-slot="detail.episodes"] [data-part="detail.countdown"],
    [data-slot="detail"][data-variant="phone"] [data-part="tab"]:not([data-active])) { font-weight: 370 !important; }
  /* Regular, 13 px and under. */
  :scope :is([data-part="coral.card-title"], [data-part="z.cw-ep"] > *, [data-slot="home"] [data-part="row.more"],
    [data-slot="nav.bottom"] > [data-part="nav.item"]:not([data-active]),
    [data-slot="detail"] [data-slot="detail.episodes"] [data-part="z.ep-meta"], [data-slot="detail"] [data-slot="detail.episodes"] [data-part="z.ep-meta"] > *,
    [data-slot="detail"] [data-slot="detail.episodes"] [data-part="z.ep-synopsis"],
    [data-slot="detail"][data-variant="phone"] [data-part="detail.genres"],
    [data-slot="detail"][data-variant="phone"] :is([data-part="coral.starring"], [data-part="coral.creators"]),
    [data-slot="detail"][data-variant="phone"] :is([data-part="coral.starring"], [data-part="coral.creators"]) > *,
    [data-slot="detail.characters"] [data-part="person.voice.name"],
    [data-slot="detail"][data-variant="phone"] [data-part="detail.info"] [data-part="fact.label"],
    [data-slot="detail"][data-variant="phone"] [data-part="detail.overview"] [data-part="detail.block-title"],
    [data-slot="detail"][data-variant="phone"] :is([data-part="detail.synonyms"], [data-part="detail.tags"]) > [data-part="detail.block-title"]::after) { font-weight: 410 !important; }
  /* Semibold (600). */
  :scope :is([data-slot="home"] [data-part="row.title"], [data-part="coral.meta"], [data-part="coral.meta"] *,
    [data-slot="nav.bottom"] > [data-part="nav.item"][data-active],
    [data-slot="detail"][data-variant="phone"] [data-part="detail.bar.title"],
    [data-slot="detail"][data-variant="phone"] [data-part="detail.buttons"] > [data-part="button"],
    [data-slot="detail"][data-variant="phone"] [data-part="tab"][data-active],
    [data-slot="detail"][data-variant="phone"] [data-part="detail.actions"] > :is([data-part="button"], [data-part="detail.action"]),
    [data-slot="detail"][data-variant="phone"] [data-part="detail.menu"] > button,
    [data-slot="detail"][data-variant="phone"] [data-part="episodes.heading"],
    [data-slot="detail.characters"] [data-part="person.name"],
    [data-slot="detail"][data-variant="phone"] [data-part="detail.info"] [data-part="fact.value"],
    [data-slot="detail"][data-variant="phone"] [data-part="detail.synonyms"] > :has(> [data-part="chip"])) { font-weight: 500 !important; }
  /* Bold (700). */
  :scope :is([data-part="coral.play"], [data-part="coral.rating"], [data-part="z.cw-title"],
    [data-slot="block.profile-header"] [data-part="button"]:is([data-dest="schedule"]:has(+ [data-dest="search"]), [data-dest="schedule"] + [data-dest="search"]),
    [data-slot="detail"][data-variant="phone"] [data-part="detail.synopsis.more"],
    [data-slot="detail"][data-variant="phone"] [data-part="detail.countdown.time"],
    [data-slot="detail"][data-variant="phone"] [data-part="episodes.ranges"] [data-part="chip"],
    [data-slot="detail"] [data-slot="detail.episodes"] [data-part="z.ep-title"], [data-slot="detail"] [data-slot="detail.episodes"] [data-part="z.ep-title"] > *,
    [data-slot="detail"] [data-slot="detail.episodes"] [data-part="z.ep-rating"] > *,
    [data-slot="detail"][data-variant="phone"] [data-part="episode"][data-variant="number"],
    [data-slot="detail"][data-variant="phone"] [data-slot="detail.relations"] [data-part="relation.type"],
    [data-slot="detail"][data-variant="phone"] :is([data-part="fact"][data-key="genres"] a, [data-part="detail.tags"] [data-part="chip"])) { font-weight: 660 !important; }
  :scope :is([data-part="coral.title"], [data-slot="detail"][data-variant="phone"] [data-part="detail.title"]) { font-weight: 670 !important; }
  :scope [data-slot="detail"] [data-slot="detail.episodes"] [data-part="z.ep-text"]::after { font-weight: 660; }
  /* Tracking: Zangetsu's styles that set no letterSpacing inherit Material 3's bodyMedium 0.25 (useMaterial3,
     no text theme), so those runs are 0.23-0.31 dp per gap wider than izumi's at the same size (measured on
     "Episodes", "Details", "Elymas Edvan", "Takeo Ootsuka", "GoHands", "Recently released"). The styles that
     set one keep it: the titles, buttons, hero meta, score tag, tags and the dock labels; the bar title is an
     AppBar title (titleLarge, 0). */
  :scope :is([data-slot="home"] [data-part="row.title"], [data-slot="home"] [data-part="row.more"], [data-part="coral.card-title"],
    [data-part="z.cw-title"], [data-part="z.cw-ep"] > *,
    [data-slot="block.profile-header"] [data-part="button"]:is([data-dest="schedule"]:has(+ [data-dest="search"]), [data-dest="schedule"] + [data-dest="search"]),
    [data-slot="search"] [data-part="search.field"], [data-part="coral.detail-meta"],
    [data-slot="detail"][data-variant="phone"] :is([data-part="detail.synopsis"], [data-part="detail.synopsis.more"], [data-part="detail.genres"], [data-part="coral.starring"], [data-part="coral.creators"], [data-part="tab"], [data-part="episodes.heading"]),
    [data-slot="detail"][data-variant="phone"] [data-part="detail.actions"] > :is([data-part="button"], [data-part="detail.action"]),
    [data-slot="detail"][data-variant="phone"] [data-slot="detail.episodes"] [data-part="detail.countdown"],
    [data-slot="detail"][data-variant="phone"] [data-part="episodes.ranges"] [data-part="chip"],
    [data-slot="detail"] [data-slot="detail.episodes"] :is([data-part="z.ep-title"], [data-part="z.ep-meta"], [data-part="z.ep-synopsis"]),
    [data-slot="detail.characters"] :is([data-part="person.name"], [data-part="person.voice.name"]),
    [data-slot="detail"][data-variant="phone"] [data-slot="detail.relations"] [data-part="coral.card-title"],
    [data-slot="detail"][data-variant="phone"] [data-part="detail.info"] :is([data-part="fact.label"], [data-part="fact.value"]),
    [data-slot="detail"][data-variant="phone"] [data-part="detail.synonyms"] > :has(> [data-part="chip"]),
    [data-slot="detail"][data-variant="phone"] :is([data-part="detail.synonyms"], [data-part="detail.tags"]) > [data-part="detail.block-title"]::after) { letter-spacing: 0.25px !important; }
  /* The resume episode keeps Zangetsu's 800 (no capture to calibrate it against). */
  :scope [data-slot="detail"]:has([data-part="detail.buttons"] > [data-action="play"][data-state="resume"]) [data-part="episode"][data-next] [data-part="z.ep-title"] > * { font-weight: 800 !important; }
}
